// helpers
const inp = $input.first().json;
const empty = v => v === undefined || v === null || v === '' || (Array.isArray(v) && v.length === 0);
const pick = (keys) => { const o = {}; for (const k of keys) if (!empty(inp[k])) o[k] = inp[k]; return o; };
const asObj = (v) => { if (empty(v)) return {}; if (typeof v === 'string') { try { return JSON.parse(v); } catch (e) { throw new Error('EFX E_VALIDATION: JSON field is not valid JSON'); } } return v; };
const asArr = (v) => empty(v) ? [] : (Array.isArray(v) ? v : String(v).split(',').map(s => s.trim()).filter(Boolean));
const bool = (v, d) => empty(v) ? d : (v === true || String(v).toLowerCase() === 'true');
const passthru = { actor: empty(inp.actor) ? undefined : inp.actor, idempotencyKey: empty(inp.idempotencyKey) ? '' : String(inp.idempotencyKey) };

const REQUIRED = ["firstName","lastName","currentClass","effDate","siteName"];
const OPTIONAL = ["reqName","reqEmail","reqDate","currentTitle","currentManagerEmail","currentManagerName","changeType","siteOld","siteNew","department","receivingManagerEmail","titleOld","titleNew","classOld","classNew","mgrOldEmail","mgrOldName","mgrNewEmail","mgrNewName","hadReports","oldReportsTo","gainingReports","newReportsFrom","hasGoogle","existingEmail","googleEmail","googleDomain","sys","adpSalaryAccess","adpSites","bossTrainingOnly","bossComm","bossCost","bossCostJobs","bossTrip","bossGriev","jrReq","jrTitle","plan306090","equip","computerRequestType","computerType","office365Required","computerPreviousUser","computerPreviousType","computerSerialNumber","creditCardUSA","creditCardLimitUSA","creditCardCanada","creditCardLimitCanada","creditCardHomeDepot","creditCardLimitHomeDepot","phoneRequestType","phonePreviousUser","phonePreviousNumber","purchasingSites","jonasJobs","equipRem","rem","comments","attachmentBase64","attachmentName","attachmentMimeType"];
const DYN = [];
const data = Object.assign({}, asObj(inp.extra), pick(REQUIRED.concat(OPTIONAL)));
const missing = REQUIRED.filter(k => empty(data[k]));
if (missing.length) throw new Error('EFX E_VALIDATION: position_change_request missing required field(s): ' + missing.join(', '));
const unknown = Object.keys(data).filter(k => !REQUIRED.includes(k) && !OPTIONAL.includes(k) && !DYN.some(p => k.startsWith(p)));
if (unknown.length) throw new Error('EFX E_VALIDATION: position_change_request unknown field(s) (not in contract): ' + unknown.join(', '));
const CLASS = ['Hourly', 'Salary'];
if (!CLASS.includes(String(data.currentClass))) throw new Error('EFX E_VALIDATION: currentClass must be Hourly|Salary');
for (const k of ['classOld', 'classNew']) if (!empty(data[k]) && !CLASS.includes(String(data[k]))) throw new Error('EFX E_VALIDATION: ' + k + ' must be Hourly|Salary');
for (const k of ['changeType', 'sys', 'equip', 'rem', 'equipRem']) if (!empty(inp[k])) data[k] = asArr(inp[k]);   // checkbox groups → arrays (UI shape)
if (empty(data.reqDate)) data.reqDate = $now.toFormat('yyyy-MM-dd');
const options = { include: bool(inp.includeRecord, false) ? ['record'] : [], allowUnverified: bool(inp.allowUnverified, false) };
return [{ json: Object.assign({ fn: 'n8n_createPositionChangeRequest', args: [data, options] }, passthru) }];
